fails = 0
for name, exp, p, a in cases:
    r = judge(p, a)
    ok = r["flagged"] == exp
    fails += not ok
    if not ok:
        print("실패", name, "기대", exp, "결과", r)
print(f"{len(cases) - fails}/{len(cases)} 통과")
sys.exit(1 if fails else 0)
